  --text-muted: #666;
  --white: #ffffff;
  --max-width: 1200px;
  --spacing: 2rem;
  --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-main);
  line-height: 1.6;
  color: var(--text-color);
  background-color: var(--white);
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  display: block;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing);
}

/* Header */
header {
  padding: 1rem 0;
  border-bottom: 1px solid #eee;
  background: var(--white);
  position: sticky;
  top: 0;
  z-index: 1000;
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 1.5rem;
  font-weight: bold;
  letter-spacing: -1px;
}

.nav-links {
  display: flex;
  gap: 2rem;
}

.nav-links a:hover {
  color: var(--accent-color);
}

@media (max-width: 600px) {
  .nav-links {
    display: none; /* Simple mobile hide, in a real app we'd add a menu toggle */
  }
  .hero h1 {
    font-size: 2rem;
  }
}

.header-actions {
  display: flex;
  gap: 1.5rem;
}

.icon-btn {
  background: none;
  border: none;
  font-size: 1.2rem;
  cursor: pointer;
  position: relative;
  padding: 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cart-count {
  position: absolute;
  top: 0;
  right: 0;
  background: var(--accent-color);
  color: white;
  font-size: 0.7rem;
  padding: 2px 6px;
  border-radius: 50%;
  font-weight: bold;
}

/* Hero Section */
.hero {
  padding: 4rem 0;
  background-color: var(--secondary-color);
  text-align: center;
}

.hero h1 {
  font-size: 3rem;
  margin-bottom: 1rem;
}

.hero p {
  font-size: 1.25rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 2rem;
}

.btn {
  display: inline-block;
  padding: 0.75rem 2rem;
  background-color: var(--primary-color);
  color: var(--white);
  border: none;
  cursor: pointer;
  transition: opacity 0.2s;
  font-weight: 600;
}

.btn:hover {
  opacity: 0.8;
}

/* Sections */
section {
  padding: 4rem 0;
}

.section-title {
  font-size: 2rem;
  margin-bottom: 2rem;
  text-align: center;
}

/* Product Grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 2rem;
}

.product-card {
  border: 1px solid #eee;
  padding: 1rem;
  transition: transform 0.2s;
}

.product-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 5px 15px rgba(0,0,0,0.1);
}

.product-image {
  background-color: #f9f9f9;
  aspect-ratio: 1/1;
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-style: italic;
  color: #ccc;
}

.product-info h3 {
  font-size: 1.1rem;
  margin-bottom: 0.5rem;
}

.product-price {
  font-weight: bold;
  color: var(--primary-color);
}

/* Deals Section */
.deals {
  background-color: #fff5f5;
}

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

@media (max-width: 768px) {
  .deals-grid {
    grid-template-columns: 1fr;
  }
}

.deal-card {
  background: var(--white);
  padding: 2rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-radius: 8px;
}

/* Editorial Content */
.editorial {
  background-color: var(--primary-color);
  color: var(--white);
}

.editorial-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

/* Footer */
footer {
  padding: 4rem 0;
  background-color: var(--secondary-color);
  border-top: 1px solid #eee;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
}

.footer-section h4 {
  margin-bottom: 1rem;
}

/* Accessibility */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

:focus-visible {
  outline: 3px solid var(--accent-color);
  outline-offset: 2px;
}
